"""Component L15 MLP down_proj #3465: a date-and-time detector.

The component is quiet on most text. It goes negative where the text is writing a date or a
time span:
- on month and weekday names (strongest), and on time-unit words such as "year(s)",
  "month(s)", "week(s)", "day(s)" and "morning" (strong), and more weakly on other time words
  ("time", "hour", "period", "ago", "today");
- on the space before a date number, after a month or weekday name (strongest) or after a
  date cue such as "in", "since", "until", "by";
- on the digits of a year: the digits after "19" or "20", and a day or year number right
  after a date cue.
Other digits are weakly negative, and everything else is near zero.

The rule reads only the newest tokens of the prefix, so it is causal. It is a hand-made
approximation: a per-token table of this component's activations would explain a bit more.
"""
import calendar

READS = ()

MONTHS = set(calendar.month_name[1:]) | {"Sept"}
WEEKDAYS = set(calendar.day_name)
TIME_UNITS = {"year", "years", "month", "months", "week", "weeks", "day", "days", "decade",
              "decades", "weekend", "morning", "evening", "night", "tomorrow", "yesterday",
              "tonight"}
WEAK_TIME_WORDS = {"time", "hour", "hours", "minute", "minutes", "period", "periods", "date",
                   "dates", "century", "centuries", "summer", "winter", "ago", "today",
                   "midnight", "noon"}
DATE_CUES = MONTHS | WEEKDAYS | {"until", "since", "early", "late", "in", "on", "by", "from",
                                 "during", "last", "next", "past", "between", "before", "after"}
YEAR_STARTS = ("18", "19", "20")
CJK_DATE_UNITS = {"年", "月", "日"}
DIGITS = "0123456789"


def is_digit(text):
    return len(text) == 1 and text in DIGITS


def step(carry, prefix, upstream):
    toks, docs = prefix.token_strings, prefix.document_ids
    cur = toks[-1].strip()
    prev = toks[-2].strip() if len(toks) > 1 and docs[-2] == docs[-1] else ""
    if is_digit(cur):
        # the digits just before this one, in the same number
        run, i = "", len(toks) - 2
        while i >= 0 and docs[i] == docs[-1] and is_digit(toks[i].strip()):
            run, i = toks[i].strip() + run, i - 1
        if run[:2] in YEAR_STARTS:
            return carry, -3.6
        # a day or year after a date cue, with at most one space in between
        gap = toks[i].strip() if i >= 0 and docs[i] == docs[-1] else "?"
        if gap == "" and i >= 1 and docs[i - 1] == docs[-1]:
            gap = toks[i - 1].strip()
        if gap in DATE_CUES:
            return carry, -3.6
        return carry, -0.2
    if cur == "":
        if prev in MONTHS or prev in WEEKDAYS:
            return carry, -8.0
        return carry, -4.0 if prev in DATE_CUES else -0.1
    if cur in MONTHS or cur in WEEKDAYS:
        return carry, -8.0
    if cur in TIME_UNITS:
        return carry, -5.0
    if cur in WEAK_TIME_WORDS:
        return carry, -2.5
    if cur in CJK_DATE_UNITS:
        return carry, -6.5
    return carry, 0.0

"""Stance polarity on the word itself and on the word after it.

Component p-82af68dd@100000/layers.15.mlp.down_proj:3468 writes into the residual stream
with a sign set by the speaker's epistemic stance. Its activation is large and rare
(it is near 0 on most tokens) and is:

- strongly negative on speculation or hope markers ("perhaps", "maybe", "hope"),
  weaker on other hedges ("probably", "might", "think", "guess");
- positive on evidence or appearance markers ("seems", "looks", "apparently",
  "evidently", "indicates", "obviously", "likely", "assume", "whether");
- negative on first-person subjects ("I", "we"), strongly so right after a hedge
  ("I hope I ...", "maybe I ..."), and positive on other subjects ("you", "he",
  "they") right after an evidence marker ("it seems like you ...", "show that they ...").

The program reads the current word and the three words before it, within the same
document, and returns the value for that rule. Everything else predicts 0.
It explains about 3% of the variance: most of the activation sits on ordinary
words with no lexical cue.
"""

READS = ()

HEDGE_STRONG = {"perhaps", "maybe", "hope", "hopefully", "hoping"}
HEDGE = {"probably", "might", "guess", "think", "believe", "suppose", "possibly",
         "suspect", "wonder", "apologize", "sure", "know", "feel"}
EVIDENCE_STRONG = {"seems", "seem", "seemed", "seemingly", "looks", "appears", "appear",
                   "apparently", "evidently", "indicates", "sounds", "obviously", "clearly"}
EVIDENCE = {"likely", "assume", "assumed", "whether", "presumably", "suggests", "shows", "show"}
FIRST_PERSON = {"i", "we"}
OTHER_SUBJECTS = {"you", "he", "she", "they"}
COMPLEMENTIZERS = {"that", "if", "like"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    doc = prefix.document_ids[-1]
    before = [
        prefix.token_strings[i].strip().lower()
        for i in range(max(0, len(prefix.token_strings) - 4), len(prefix.token_strings) - 1)
        if prefix.document_ids[i] == doc
    ]
    hedge = any(w in HEDGE_STRONG or w in HEDGE for w in before)
    evidence = any(w in EVIDENCE_STRONG or w in EVIDENCE for w in before)
    if word in HEDGE_STRONG:
        value = -3.5
    elif word in HEDGE:
        value = -1.0
    elif word in EVIDENCE_STRONG:
        value = 2.0
    elif word in EVIDENCE:
        value = 1.0
    elif word in FIRST_PERSON:
        value = -3.0 if hedge else -0.5
    elif word in OTHER_SUBJECTS:
        value = 2.0 if evidence else 0.3
    elif word in COMPLEMENTIZERS:
        value = 1.0 if evidence else (-1.0 if hedge else 0.0)
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP neuron 3469 (this component), read off the current token.

The component is almost exactly one MLP hidden unit: its input vector is ~0.86 on
hidden unit 3469 and small elsewhere, so its activation is that unit's value, scaled.
It is sparse and signed. Most tokens sit near 0. It is strongly positive on a few
kinds of token:

- URL and file-path separators and hosts: "://", " /", ' "/', "(/", "www", ".com",
  "/org", "/io", "github", where a domain or package name is about to start;
- prepositions that often precede a place or organisation name: " of", " in", " at",
  " from", " by";
- opening quotes and brackets that start a string, path or code literal: ' "', " `",
  '("', " '".

Each class gets its mean activation on training rows. Everything else gets the mean of
the rest. Only the current token is read, so the program is stateless.
"""

READS = ()

SEPARATORS = {" /", ' "/', "'/", "(/", " `/", " ./", " (/", "/", "://"}
HOSTS = {"www", " www", ".com", " com", "/com", "/org", " org", "/io", "github", '"github', "/apache", "/google", "/java"}
PREPOSITIONS = {" of", " in", " at", " from", " by"}
OPENERS = {' "', " `", '("', "('", " “", " '"}

LEVELS = (
    (SEPARATORS, 1.7),
    (HOSTS, 4.0),
    (PREPOSITIONS, 0.5),
    (OPENERS, 0.9),
)
REST = 0.04


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    for words, level in LEVELS:
        if token in words:
            return None, level
    return None, REST

"""Layer-15 MLP unit 3471 (down_proj component 3471), a rough word-level predictor.

The unit is largest on the names of formal public occasions (ceremony, finale, awards,
annual events, weddings, premieres, conferences, and Chinese 婚礼, 颁奖, 仪式, 典礼,
闭幕式, 大会, 发布会) and negative on casual, personal, everyday talk (laughed, walked,
friends, holiday, decorations). This program predicts that from the current token only.
It explains very little of the variance: the unit's sign and size depend on the wider
context, which a word list cannot see.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

EVENT_STRONG = {
    "ceremony", "finale", "vows", "wedding", "weddings", "bride", "groom", "premiere",
    "banquet", "gala", "unveiled", "annual", "annually", "award", "awards", "awarded",
    "presentation", "presented", "tribute", "concert", "parade", "festival", "conference",
    "summit", "symposium", "finals", "inaugurated", "inauguration",
}
EVENT_WEAK = {"opening", "closing", "launch", "championship", "tournament", "match", "final"}
EVENT_ZH = ("婚礼", "颁奖", "仪式", "典礼", "闭幕", "开幕", "大会", "发布会", "庆典", "峰会", "论坛")
CASUAL = {"holiday", "festive", "decorations", "laughed", "smiled", "walked", "friend",
          "friends", "drinking", "drink", "talked", "cook"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    if any(z in word for z in EVENT_ZH):
        value = 3.5
    elif word in EVENT_STRONG:
        value = 1.2
    elif word in EVENT_WEAK:
        value = 0.4
    elif word in CASUAL:
        value = -0.5
    else:
        value = 0.0
    return carry, value

"""Layer 15, MLP neuron-direction component 3488 (down_proj).

This component is mostly quiet, with rare large positive bursts. Its activation is
hard to explain with simple rules: the current token alone explains only a few percent
of its variance, and the best readable pieces are below.

The program reads two things from the text so far:
  - the previous token: after a command or library stem such as `grep`, `cat`, `str`
    (as in `str_replace`), `trim`, `utils`, `#include`, `import`, the next token is
    strongly positive, most of all the `-` flag after `grep`;
  - the current token: assignment and comment markers in code (`=`, `:=`, `<-`, `//`, `#`)
    are mildly positive, names of string and list utilities (replace, trim, strip,
    filter, sort, remove, ...) are positive, and chat-template role markers are slightly
    negative.
The first token of each document is silent.
"""

READS = ()

AFTER_COMMAND = {
    "grep", "cat", "str", "trim", "utils", "util", "replace", "#include", "import", "std",
}
ASSIGN_OR_COMMENT = {"=", ":=", "<-", "//", "#"}
STRING_LIST_UTILS = {
    "replace", "trim", "strip", "filter", "sort", "sorted", "remove", "split", "join",
    "str", "string", "strings", "utils", "util", "np", "normalize", "simplify", "lower", "upper",
}
CHAT_MARKERS = {"user", "assistant", "system"}
BASE = 0.03


def step(carry, prefix, upstream):
    if len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    text = prefix.token_strings[-1]
    word = text.strip().lower().lstrip("._/")
    before = prefix.token_strings[-2].strip()
    if before == "grep":
        return carry, 3.0
    if before in AFTER_COMMAND:
        return carry, 1.0
    if text.strip() in ASSIGN_OR_COMMENT:
        return carry, 0.45
    if word in STRING_LIST_UTILS:
        return carry, 0.8
    if "<|" in text or word in CHAT_MARKERS:
        return carry, -0.1
    return carry, BASE

"""Rough token-class predictor for layers.15.mlp.down_proj:3496.

This component reads a diffuse direction of layer 15's MLP hidden state (its
weight vector is dominated by hidden unit 3496, then spread thinly over ~6000
other units). It has no clean concept: it barely fires as a feature, and its
activation is only weakly tied to the current token. This program predicts the
activation from the newest token's broad class: digits lean slightly positive,
bare whitespace leans negative, and the first token of a row is about zero.
Everything else gets the overall mean. Class means were measured on training rows.
"""

import regex

READS = ()

MEAN = -0.025
CLASS_MEAN = {"digits": 0.023, "han": 0.009, "space": -0.069}


def token_class(text):
    if text.strip() == "" and "\n" not in text:
        return "space"
    if regex.fullmatch(r"\s?\p{N}+", text):
        return "digits"
    if regex.fullmatch(r"\s?\p{Han}+", text):
        return "han"
    return "other"


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return carry, 0.0
    text = prefix.token_strings[-1]
    return carry, CLASS_MEAN.get(token_class(text), MEAN)

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:3502: a diffuse, high-variance feature.

Its activation is large in both directions (spread about 0.75, tails to -23 and +14), but
the current token's class explains almost none of it. Its class means differ only slightly:
content words (open-class English words, by WordNet) sit a little below zero, and
punctuation a little above. The program predicts each token's class mean; that explains
well under 1% of the variance, and is what the simple readable version can say.
"""

import wordnet

READS = ()

MEANS = {"content": -0.01, "punct": 0.10, "digit": 0.05, "space": 0.06, "other": 0.04}


def token_class(s):
    w = s.strip()
    if w == "":
        return "space"
    if not any(ch.isalnum() for ch in w):
        return "punct"
    if w.isdigit():
        return "digit"
    if w.isalpha() and s[:1] == " " and wordnet.parts_of_speech(w.lower()):
        return "content"
    return "other"


def step(carry, prefix, upstream):
    return carry, MEANS[token_class(prefix.token_strings[-1])]

"""Token-class predictor. The component's activation has a small mean offset by kind of
token: whitespace (newlines most of all) and sentence punctuation run slightly negative,
words and digits sit near the average. Token identity explains only about 0.1% of the
variance, so this is a weak description, not a mechanism."""
import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

MEANS = {"newline": -0.083, "space": -0.041, "punct": -0.051, "other": -0.027}


def kind(text: str) -> str:
    if re.fullmatch(r"\s+", text):
        return "newline" if "\n" in text else "space"
    if re.fullmatch(r"\s?[.,;:!?)\"']+", text):
        return "punct"
    return "other"


def step(carry, prefix, upstream: Mapping):
    return carry, MEANS[kind(prefix.token_strings[-1])]

"""Copula / passive-auxiliary detector.

Fires on the auxiliary slot in front of a predicate: forms of the verb "to be"
(and the Chinese passive marker 被), and the words that complete a be-verb
before its complement, such as "not" or "also" in "is not used", and the
"n't" of "isn't". It is strongest after a modal or perfect auxiliary
("can be", "has been"), and weak in existential or demonstrative frames
("there is", "this is", "what is"). "it's" (it is) counts as a be-form.

In a formal, impersonal document the copula runs higher, and in chatty
first-person text it runs lower: the running share of personal pronouns
(I, you, we, he, she, they) pulls it down, and the running average word
length (a rough formality cue) pushes it up. Both are carried through the
document, and reset at each new document.
"""

READS = ()

# Forms of "be" by typical strength: "was", "were", "été", "être" strongest;
# "is", "are", "be", "been", "being" middling; "am", "'m", "'re", "est" weakest.
STRONG = {" were", " was", " été", " être"}
MIDDLE = {" is", " are", " be", " being", " been", " ser", " era"}
WEAK = {" am", "'m", "’m", "'re", "’re", " est", " sono", " é"}
PASSIVE_MARKER = {"被", " 被"}
BE_FORMS = STRONG | MIDDLE | WEAK | PASSIVE_MARKER

# Negation and adverbs that sit between a be-form and a participle.
BETWEEN = {
    " not", " also", " often", " usually", " typically", " originally",
    " initially", " commonly", " currently", " normally", " generally",
    " primarily", " previously", " specifically", " widely", " mostly",
    " actually",
}
# The "n't" of "isn't", "wasn't" and the stems they follow.
NT_TOKENS = {"'t", "’t"}
NT_STEMS = {" isn", " aren", " wasn", " weren"}
# Subjects that make a following "'s" the copula: "it's", "that's", "what's".
SUBJECTS_FOR_S = {" it", " It", " he", " He", " she", " She", " that", " That",
                  " what", " What", " there", " There", " who", " Who"}

# Words before a be-form that make a participle expected.
MODAL_PERFECT = {" can", " will", " may", " shall", " should", " cannot", " has", " have", " had"}
# Adverbs and negation before a be-form: "not is", "also are".
NEG_BEFORE = {" not", " also", " never", " always", " often", " still", " only", " already"}
# Existential and demonstrative subjects: "there is", "this is", "what is".
EXPLETIVE_BEFORE = {" there", " There", " here", " Here", " this", " This",
                    " these", " These", " what", " What"}
# Personal pronouns, whose running share marks chatty first-person text.
PERSONAL = {" I", " you", " You", " we", " We", " me", " my", " your",
            " he", " she", " He", " She", " they", " They"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]
    before = "" if new_doc else prefix.token_strings[-2]
    # Running state of the document before this token: tokens, personal pronouns, characters.
    n, personal, chars = (0, 0, 0) if new_doc or carry is None else carry
    carry = (n + 1, personal + (tok in PERSONAL), chars + len(tok))

    if tok in BETWEEN or tok in NT_TOKENS:
        # The slot right after a be-verb: "is not", "was also", "isn't".
        is_after_be = before in BE_FORMS or before in NT_STEMS
        return carry, (4.0 if is_after_be else 0.0)
    if tok in ("'s", "’s"):
        return carry, (2.0 if before in SUBJECTS_FOR_S else 0.0)
    if tok in STRONG:
        value = 6.0
    elif tok in MIDDLE:
        value = 4.5
    elif tok in WEAK or tok in PASSIVE_MARKER:
        value = 2.5
    else:
        return carry, 0.0
    if new_doc:
        return carry, 0.0

    if before in MODAL_PERFECT:
        value += 2.5
    elif before in NEG_BEFORE:
        value += 2.0
    elif before in EXPLETIVE_BEFORE:
        value -= 3.0
    if n >= 10:
        value += 0.55 * (chars / n - 4.3) - 22 * (personal / n - 0.015)
    return carry, value
